-- Pure validation tests: no persisted patient records, no application grants.
DO $test$ DECLARE p jsonb:=$packet${"schemaVersion": "1", "action": "create", "requestId": "00000000-0000-4000-8000-000000000030", "tenantId": "00000000-0000-4000-8000-000000000020", "clientId": "00000000-0000-4000-8000-000000000002", "medicationId": "00000000-0000-4000-8000-000000000001", "actorId": "00000000-0000-4000-8000-000000000012", "expectedHeadId": null, "expectedRevision": 0, "entry": {"kind": "reconciliation", "title": "Vollständiger Vorgang reconciliation", "plannedAt": "2026-10-15T12:13:14.123456Z", "occurredAt": null, "medicationId": "00000000-0000-4000-8000-000000000001", "clientId": "00000000-0000-4000-8000-000000000002", "orderVersion": "2026-10-15T12:13:14.123456Z", "sourceReview": {"planFingerprint": "sha256:1111111111111111111111111111111111111111111111111111111111111111", "documentIds": ["00000000-0000-4000-8000-000000000003"], "discrepancies": [], "allergyState": "documented", "allergyText": "Latex dokumentiert", "clarification": "", "decision": "confirmed"}, "order": {"medicationName": "Metamizol", "activeIngredient": "Metamizol-Natrium", "strength": "500 mg", "form": "Tablette", "dose": "1", "unit": "Tablette", "route": "oral", "prescriber": "Ärztliche Verordnung", "validFrom": "2026-10-01", "validUntil": null, "indication": "Dokumentierte Schmerzindikation", "isPrn": false, "minimumIntervalMinutes": null, "maximumDose": null, "maximumDoseUnit": "", "maximumPeriodHours": null}, "schedule": {"versionId": null, "effectiveFrom": null, "slots": [], "changeReason": ""}, "administration": {"outcome": "planned", "actualAt": null, "actualDose": null, "unit": "", "route": "", "performedBy": null, "deviationReason": "", "prnIndication": "", "precedingAdministrationIds": [], "intervalMinutes": null, "maximumPeriodDose": null}, "effect": {"administrationId": null, "observedAt": null, "observation": "", "action": "", "painScore": null}, "safety": {"state": "not_observed", "observation": "", "suspectedRelation": "", "reaction": "", "clinicianContact": "", "followUp": ""}, "witness": {"required": false, "profileId": null, "assertion": "not_required", "signedAt": null, "signatureId": null, "qualificationEvidence": ""}, "stock": {"operation": "none", "packageId": null, "batch": "", "expiry": null, "quantity": null, "unit": "", "balanceBefore": null, "balanceAfter": null, "reason": "", "responsibleBy": null}, "orderStatus": {"current": "active", "next": "unchanged", "effectiveAt": null, "reason": "", "authorizationId": null, "followUpPlanId": null}, "correction": {"targetEventId": null, "reason": "", "replacementEventId": null, "approvedBy": null, "approvedAt": null}, "lifecycle": "open"}, "reason": "", "original": null, "sources": {"order": {"id": "00000000-0000-4000-8000-000000000001", "revision": 1, "recordedAt": "2026-10-15T12:13:14.123456Z", "fingerprint": "sha256:1111111111111111111111111111111111111111111111111111111111111111", "medicationId": "00000000-0000-4000-8000-000000000001", "clientId": "00000000-0000-4000-8000-000000000002", "status": "active", "updatedAt": "2026-10-15T12:13:14.123456Z", "payload": {"name": "Metamizol", "active_ingredient": "Metamizol-Natrium", "strength": "500 mg", "form": "Tablette", "prescribed_dose": "1", "dose_unit": "Tablette", "route": "oral", "prescribed_by": "Ärztliche Verordnung", "start_date": "2026-10-01", "end_date": null, "indication": "Dokumentierte Schmerzindikation", "is_prn": false, "minimum_interval_minutes": null, "maximum_dose": null, "maximum_dose_unit": "", "maximum_period_hours": null}}, "allergies": {"id": "00000000-0000-4000-8000-000000000002", "revision": 1, "recordedAt": "2026-10-15T12:13:14.123456Z", "fingerprint": "sha256:2222222222222222222222222222222222222222222222222222222222222222", "state": "documented", "text": "Latex dokumentiert"}, "documents": [{"id": "00000000-0000-4000-8000-000000000003", "revision": 1, "recordedAt": "2026-10-15T12:13:14.123456Z", "fingerprint": "sha256:3333333333333333333333333333333333333333333333333333333333333333", "title": "Ärztliche Verordnung", "version": "2026-10-15"}], "administrations": [{"id": "00000000-0000-4000-8000-000000000004", "revision": 1, "recordedAt": "2026-10-15T12:13:14.123456Z", "fingerprint": "sha256:4444444444444444444444444444444444444444444444444444444444444444", "status": "administered", "occurredAt": "2026-10-15T09:14:15.654321Z", "dose": "1", "unit": "Tablette", "route": "oral"}], "statusEvents": [{"id": "00000000-0000-4000-8000-000000000005", "revision": 1, "recordedAt": "2026-10-15T12:13:14.123456Z", "fingerprint": "sha256:5555555555555555555555555555555555555555555555555555555555555555", "previousStatus": "active", "nextStatus": "paused"}], "witnesses": [{"id": "00000000-0000-4000-8000-000000000006", "revision": 1, "recordedAt": "2026-10-15T12:13:14.123456Z", "fingerprint": "sha256:6666666666666666666666666666666666666666666666666666666666666666", "profileId": "00000000-0000-4000-8000-000000000007", "active": true, "qualificationState": "current_documented"}, {"id": "00000000-0000-4000-8000-000000000012", "revision": 1, "recordedAt": "2026-10-15T12:13:14.123456Z", "fingerprint": "sha256:7777777777777777777777777777777777777777777777777777777777777777", "profileId": "00000000-0000-4000-8000-000000000012", "active": true, "qualificationState": "registered_nurse_current"}], "stockMovements": [{"id": "00000000-0000-4000-8000-000000000008", "revision": 1, "recordedAt": "2026-10-15T12:13:14.123456Z", "fingerprint": "sha256:8888888888888888888888888888888888888888888888888888888888888888", "packageId": "00000000-0000-4000-8000-000000000009", "operation": "receipt", "quantity": "10", "unit": "Tablette", "balanceAfter": "10"}]}}$packet$::jsonb;bad jsonb;key text;facts jsonb;checks integer:=0;BEGIN
facts:=care_private.medication_native_order(p#>'{sources,order,payload}');
IF facts IS DISTINCT FROM p#>'{entry,order}' THEN RAISE EXCEPTION 'Native projection mismatch';END IF;
FOR key IN SELECT jsonb_object_keys(p#>'{entry,order}') LOOP
 bad:=jsonb_set(p,ARRAY['entry','order',key],case when key='isPrn' then 'true'::jsonb when key='validUntil' then '"2026-12-31"'::jsonb when key='dose' then '"2"'::jsonb when key='validFrom' then '"2026-10-02"'::jsonb else '"changed"'::jsonb end);
 BEGIN PERFORM care_private.validate_medication_packet(bad,(p->>'actorId')::uuid,p->'sources');RAISE EXCEPTION 'Native order field change accepted: %',key;EXCEPTION WHEN check_violation OR insufficient_privilege THEN checks:=checks+1;END;
END LOOP;
FOR key IN SELECT jsonb_object_keys(p#>'{sources,order,payload}') LOOP
 BEGIN PERFORM care_private.medication_native_order((p#>'{sources,order,payload}')-key);RAISE EXCEPTION 'Missing native field accepted: %',key;EXCEPTION WHEN check_violation THEN checks:=checks+1;END;
END LOOP;
bad:=p#-'{sources,order,payload,prescribed_dose}';
BEGIN PERFORM care_private.validate_medication_packet(bad,(bad->>'actorId')::uuid,bad->'sources');RAISE EXCEPTION 'Legacy free-text dose promoted to confirmed';EXCEPTION WHEN check_violation THEN checks:=checks+1;END;
bad:=jsonb_set(bad,'{entry,sourceReview,decision}','"unresolved"');bad:=jsonb_set(bad,'{entry,lifecycle}','"open"');PERFORM care_private.validate_medication_packet(bad,(bad->>'actorId')::uuid,bad->'sources');checks:=checks+1;
bad:=jsonb_set(bad,'{entry,lifecycle}','"completed"');BEGIN PERFORM care_private.validate_medication_packet(bad,(bad->>'actorId')::uuid,bad->'sources');RAISE EXCEPTION 'Unknown native dose completed';EXCEPTION WHEN check_violation THEN checks:=checks+1;END;
IF checks<>35 THEN RAISE EXCEPTION 'Native order test count mismatch: %',checks;END IF;
END $test$;
